// å¼·åŒ–ç”»é¢ã®æ•°å€¤ç›´æ¥å…¥åŠ›ã‚’ã€0ã€œãã®é …ç›®ã¸æŒ¯ã‚Œã‚‹æœ€å¤§ãƒã‚¤ãƒ³ãƒˆã¸æ­£è¦åŒ–ã™ã‚‹ã€‚
// inputMode=numeric ã§ã‚‚è²¼ã‚Šä»˜ã‘ã§ã¯è¨˜å·ç­‰ãŒå…¥ã‚Šå¾—ã‚‹ãŸã‚ã€æ•´æ•°ã ã‘ã‚’å—ã‘ä»˜ã‘ã‚‹ã€‚
const directEnhancePointAmount = (rawValue, maxValue) => {
  const text = String(rawValue ?? '').trim();
  const max = Math.max(0, Math.floor(Number(maxValue) || 0));
  if (!/^\d+$/.test(text)) return 0;
  const parsed = Number(text);
  const wanted = Number.isFinite(parsed) ? Math.floor(parsed) : Number.MAX_SAFE_INTEGER;
  return Math.min(Math.max(0, wanted), max);
};

// å¼·åŒ–ã®ä¸‹æ›¸ã(plan)ã‚’å½“ã¦ã¯ã‚ãŸã€Œå¼·åŒ–å¾Œã®ãƒã‚¹ãƒ¢ãƒ³ã€ã‚’ã€ä¿å­˜ãƒ‡ãƒ¼ã‚¿ã«è§¦ã‚Œãšã«ä½œã‚‹ã€‚
